package com.dianping.shopdetail.model.request;

import com.dianping.shopdetail.exception.ShopReviewException;
import com.dianping.shopdetail.model.ShopReview;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;

/** 请求不包含可信作者身份，评分在此精确转换为内部整数。 */
public record PublishShopReviewRequest(String requestId, BigDecimal overallScore, BigDecimal tasteScore,
                                       BigDecimal environmentScore, BigDecimal serviceScore,
                                       String content, List<String> tags) {
    public ShopReview toReview(Long shopId, Long userId) {
        return ShopReview.create(shopId, userId, requestId, score(overallScore), score(tasteScore),
                score(environmentScore), score(serviceScore), content, tags, LocalDateTime.now());
    }
    private static int score(BigDecimal value) {
        if (value == null) throw new ShopReviewException(400, "四项评分均为必填");
        try { return value.movePointRight(1).intValueExact(); }
        catch (ArithmeticException error) { throw new ShopReviewException(400, "评分格式不合法"); }
    }
}

package com.dianping.shopdetail.model.request;

import com.dianping.shopdetail.exception.RecommendDishException;

/** 商详预览可取 6 条，独立浏览默认每页 12 条。 */
public record RecommendDishPageRequest(Long shopId, Long current, Integer size) {
    public RecommendDishPageRequest {
        if (shopId == null || shopId <= 0) throw new RecommendDishException(400, "店铺标识必须为正数");
        current = current == null ? 1L : current;
        size = size == null ? 12 : size;
        if (current <= 0 || size <= 0 || size > 50) throw new RecommendDishException(400, "页码须为正数，每页数量须为 1～50");
        try { Math.multiplyExact(current - 1, size.longValue()); }
        catch (ArithmeticException error) { throw new RecommendDishException(400, "页码超出支持范围"); }
    }
    public long offset() { return (current - 1) * size; }
}

package com.dianping.shopdetail.model.request;
import com.dianping.shopdetail.exception.ShopDetailException;
/** 新增列表的分页请求；溢出页码在进入仓储前拒绝。 */
public record ShopDetailPageRequest(Long shopId, long current, int size) {
    public ShopDetailPageRequest {
        if (shopId == null || shopId <= 0) throw new ShopDetailException(400, "店铺 ID 必须为正整数");
        if (current < 1 || size < 1 || size > 50) throw new ShopDetailException(400, "页码须为正数，每页数量须为 1～50");
        try { Math.multiplyExact(current - 1, (long) size); }
        catch (ArithmeticException error) { throw new ShopDetailException(400, "页码超出支持范围"); }
    }
    public long offset() { return (current - 1) * size; }
}

package com.dianping.shopdetail.model.request;

import com.dianping.shopdetail.exception.ShopReviewException;

public record ShopReviewPageRequest(Long shopId, Long current) {
    public static final int SIZE = 10;
    public ShopReviewPageRequest {
        if (shopId == null || shopId <= 0 || current == null || current <= 0
                || current > Long.MAX_VALUE / SIZE) throw new ShopReviewException(400, "店铺或页码不合法");
    }
    public long offset() { return (current - 1) * SIZE; }
}

