package com.dianping.shopdetail.service;

import com.dianping.shopdetail.enums.ReviewTag;
import com.dianping.shopdetail.model.*;
import com.dianping.shopdetail.repository.*;
import com.dianping.shopdetail.exception.ShopDetailException;
import java.time.LocalDateTime;
import java.util.*;
import java.util.regex.Pattern;

/** 商详联合查询与跨对象业务规则；不依赖任务引擎、HTTP 或持久化框架。 */
public class ShopDetailDomainService {
    public static final int VOUCHER_PREVIEW_SIZE = 2;
    public static final int SETMEAL_PREVIEW_SIZE = 4;
    public static final int DISH_PREVIEW_SIZE = 6;
    public static final int REVIEW_PREVIEW_SIZE = 3;
    public static final int BLOG_PREVIEW_SIZE = 4;
    private final ShopDetailRepository details;
    private final ShopVoucherRepository vouchers;
    private final ShopSetmealRepository meals;
    private final ShopReviewRepository reviews;
    private final RecommendDishRepository dishes;

    public ShopDetailDomainService(ShopDetailRepository details, ShopVoucherRepository vouchers,
            ShopSetmealRepository meals, ShopReviewRepository reviews, RecommendDishRepository dishes) {
        this.details = Objects.requireNonNull(details);
        this.vouchers = Objects.requireNonNull(vouchers);
        this.meals = Objects.requireNonNull(meals);
        this.reviews = Objects.requireNonNull(reviews);
        this.dishes = Objects.requireNonNull(dishes);
    }

    /** 同步联合查询；直接组合仓储结果，查询异常交由调用方处理。 */
    public ShopDetailAggregate getShopDetail(Long shopId, Long viewerId) {
        ShopDetailAggregate aggregate = new ShopDetailAggregate();
        aggregate.setShop(base(shopId));
        aggregate.setVouchers(vouchers.page(shopId, 1, VOUCHER_PREVIEW_SIZE, LocalDateTime.now()));
        aggregate.setSetmeals(meals.pageWithTotal(shopId, 1, SETMEAL_PREVIEW_SIZE));
        aggregate.setRecommendations(dishes.pageWithTotal(shopId, 1, DISH_PREVIEW_SIZE));
        aggregate.setRecommendedIds(recommendedIds(viewerId, aggregate.getRecommendations()));
        aggregate.setReviews(reviews.pageWithTotal(shopId, 1, REVIEW_PREVIEW_SIZE));
        aggregate.setReviewSummary(reviews.summarize(shopId));
        aggregate.setBlogs(details.blogs(shopId, 1, BLOG_PREVIEW_SIZE, viewerId));
        return enrichShopDetail(aggregate, LocalDateTime.now().minusDays(90));
    }

    public ShopDetailAggregate getShopDetail(Long shopId) { return getShopDetail(shopId, null); }

    public ShopBaseInfo base(Long shopId) {
        if (shopId == null || shopId <= 0) throw new ShopDetailException(400, "店铺 ID 必须为正整数");
        return details.findShop(shopId).orElseThrow(() -> new ShopDetailException(404, "店铺不存在"));
    }

    public ShopPage<ShopVoucher> vouchers(Long shopId, long current, int size) {
        return vouchers.page(shopId, current, size, LocalDateTime.now());
    }

    public ShopPage<ShopSetmeal> setmeals(Long shopId, long current, int size) {
        return meals.pageWithTotal(shopId, current, size);
    }

    public ShopPage<RecommendDish> recommendations(Long shopId, long current, int size) {
        return dishes.pageWithTotal(shopId, current, size);
    }

    public Set<Long> recommendedIds(Long viewerId, ShopPage<RecommendDish> page) {
        if (viewerId == null || page.records().isEmpty()) return Set.of();
        return Set.copyOf(dishes.recommendedIds(viewerId, page.records().stream().map(RecommendDish::id).toList()));
    }

    public ShopPage<ShopReview> reviews(Long shopId, long current, int size) {
        return reviews.pageWithTotal(shopId, current, size);
    }

    public ShopReviewSummary statistics(Long shopId) { return reviews.summarize(shopId); }

    public ShopPage<ShopVisitBlog> blogs(Long shopId, long current, int size, Long viewerId) {
        return details.blogs(shopId, current, size, viewerId);
    }

    /** 根据评价、博客及店铺位置补齐衍生数据。 */
    public ShopDetailAggregate enrichShopDetail(ShopDetailAggregate aggregate, LocalDateTime since) {
        Long shopId = aggregate.getShop().id();
        var reviewEvidence = reviewEvidence(shopId, since);
        var blogEvidence = blogEvidence(shopId, since);
        aggregate.setDecisionTags(mergeDecisionTags(reviewEvidence, blogEvidence));
        aggregate.setReviewTags(mergeDecisionTags(reviewEvidence, List.of()));
        aggregate.setRelatedUnavailableReason(relatedUnavailableReason(aggregate.getShop()));
        aggregate.setRelatedShops(related(aggregate.getShop(), 1, 6));
        return aggregate;
    }

    public List<TagEvidence> reviewEvidence(Long shopId, LocalDateTime since) {
        return details.reviewEvidence(shopId, since, 200);
    }

    public List<TagEvidence> blogEvidence(Long shopId, LocalDateTime since) {
        return details.blogEvidence(shopId, since, 50);
    }

    public ShopPage<ShopRelatedShop> related(ShopBaseInfo center, long current, int size) {
        return relatedUnavailableReason(center) == null ? details.related(center, current, size) : null;
    }

    public String relatedUnavailableReason(ShopBaseInfo center) {
        if (!hasCoordinates(center)) return "缺少位置信息，暂无法推荐周边店铺";
        if (center.typeId() == null) return "缺少店铺类型，暂无法推荐周边店铺";
        return null;
    }

    private static final Pattern SENTENCE = Pattern.compile("(?<=[。！？!?；;，,\\n\\r])");
    private static final Pattern UNCERTAIN = Pattern.compile("不|没|无|未|差|难|慢|脏|贵|糟|一般|但是|不过|然而|听说|据说|可能|似乎|希望|要是|如果|据称|未必|算不上");
    private static final Map<ReviewTag, List<String>> PHRASES = Map.of(
            ReviewTag.TASTY, List.of("味道好", "很好吃", "好吃", "味道不错"),
            ReviewTag.NICE_ENVIRONMENT, List.of("环境好", "环境优美", "环境舒适"),
            ReviewTag.FRIENDLY_SERVICE, List.of("服务热情", "服务很好", "服务周到"),
            ReviewTag.GOOD_VALUE, List.of("价格实惠", "性价比高", "价格便宜"),
            ReviewTag.CLEAN, List.of("干净卫生", "很干净", "卫生很好"),
            ReviewTag.CONVENIENT_LOCATION, List.of("交通方便", "交通便利"),
            ReviewTag.FAST_SERVICE, List.of("出餐快", "上菜快"),
            ReviewTag.EASY_PARKING, List.of("停车方便", "停车便利"));

    public List<ShopDecisionTag> mergeDecisionTags(List<TagEvidence> reviews, List<TagEvidence> blogs) {
        var users = new EnumMap<ReviewTag, Set<Long>>(ReviewTag.class);
        for (var evidence : reviews) {
            if (evidence.userId() == null) continue;
            for (var tag : evidence.tags()) users.computeIfAbsent(tag, key -> new HashSet<>()).add(evidence.userId());
        }
        for (var evidence : blogs) {
            if (evidence.userId() == null || evidence.text() == null) continue;
            String plain = evidence.text().replaceAll("<[^>]*>", " ");
            for (String sentence : SENTENCE.split(plain)) {
                if (sentence.contains("?") || sentence.contains("？") || sentence.contains("吗") || sentence.contains("是否")
                        || UNCERTAIN.matcher(sentence.replace("不错", "很好")).find()) continue;
                for (var tag : ReviewTag.values()) {
                    if (PHRASES.get(tag).stream().anyMatch(sentence::contains))
                        users.computeIfAbsent(tag, key -> new HashSet<>()).add(evidence.userId());
                }
            }
        }
        return Arrays.stream(ReviewTag.values())
                .filter(tag -> users.getOrDefault(tag, Set.of()).size() >= 2)
                .sorted(Comparator.<ReviewTag>comparingInt(tag -> users.get(tag).size()).reversed()
                        .thenComparingInt(Enum::ordinal))
                .limit(5).map(tag -> new ShopDecisionTag(tag.name(), tag.displayName(), users.get(tag).size())).toList();
    }

    public boolean hasCoordinates(ShopBaseInfo shop) {
        return shop != null && shop.x() != null && shop.y() != null
                && Double.isFinite(shop.x()) && Double.isFinite(shop.y())
                && shop.x() >= -180 && shop.x() <= 180 && shop.y() >= -90 && shop.y() <= 90;
    }

    /** 球面直线距离，米；周边展示和范围筛选共用。 */
    public double distanceMeters(double x1, double y1, double x2, double y2) {
        double dy = Math.toRadians(y2 - y1), dx = Math.toRadians(x2 - x1);
        double a = Math.pow(Math.sin(dy / 2), 2) + Math.cos(Math.toRadians(y1))
                * Math.cos(Math.toRadians(y2)) * Math.pow(Math.sin(dx / 2), 2);
        return 6371008.8 * 2 * Math.asin(Math.sqrt(Math.min(1, a)));
    }
}

package com.dianping.shared.taskchain;

import com.dianping.shared.taskchain.enums.ProcessPhase;
import com.dianping.shared.taskchain.enums.TaskType;
import com.dianping.shared.taskchain.enums.NodeExecutionStatus;
import com.dianping.shared.taskchain.enums.ExecutionMode;
import com.dianping.shared.taskchain.model.PhaseConfig;
import com.dianping.shared.taskchain.model.TaskContext;
import com.dianping.shared.taskchain.model.TaskNodeHolder;
import com.dianping.shared.taskchain.model.TaskNodeRegistry;
import com.dianping.shared.taskchain.service.TaskChainEngine;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.junit.jupiter.params.provider.CsvSource;

import java.time.Duration;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.Executor;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.Executors;

import static org.junit.jupiter.api.Assertions.*;

class TaskChainEngineTest {
    @ParameterizedTest
    @ValueSource(booleans = {false, true})
    void queueWaitingConsumesTheStageBudgetAndCancelledWorkNeverStarts(boolean required) throws Exception {
        var occupied = new CountDownLatch(1);
        var release = new CountDownLatch(1);
        var ran = new AtomicBoolean();
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("queued", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.IO_BOUND, required, c -> ran.set(true)));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(1);
             var io = new ThreadPoolExecutor(1, 1, 0, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(1))) {
            try {
                io.execute(() -> { occupied.countDown(); awaitIgnoringInterrupts(release); });
                assertTrue(occupied.await(2, TimeUnit.SECONDS));
                var result = new TaskChainEngine(registry, cpu, io, Duration.ofMillis(120))
                        .executeChain("shop", new TaskContext<Integer, String>(7));
                assertEquals(!required, result.isSuccess());
                assertEquals(NodeExecutionStatus.TIMED_OUT, result.getNodeResults().getFirst().status());
                release.countDown();
                io.shutdown();
                assertTrue(io.awaitTermination(2, TimeUnit.SECONDS));
                assertFalse(ran.get());
            } finally { release.countDown(); }
        }
    }

    @Test
    void failedParallelWritesDoNotConflictWithAcceptedSuccessfulWrites() {
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("failed", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.IO_BOUND, false, c -> {
                    c.setAttribute("same", "无效");
                    c.setOutput("无效响应");
                    throw new IllegalStateException("可选失败");
                }));
        registry.register(new TaskNodeHolder<Integer, String>("success", "shop", ProcessPhase.DATA_PROCESSING,
                1, TaskType.CPU_BOUND, true, c -> { c.setAttribute("same", "有效"); c.setOutput("有效响应"); }));
        registry.freeze();
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(2))
                    .executePhaseChain("shop", new TaskContext<Integer, String>(7),
                            List.of(new PhaseConfig(ProcessPhase.DATA_PROCESSING, ExecutionMode.PARALLEL, Duration.ofSeconds(2))));
            assertTrue(result.isSuccess());
            assertEquals("有效", result.getAttribute("same"));
            assertEquals("有效响应", result.getOutput());
            assertEquals(NodeExecutionStatus.FAILED, result.getNodeResults().getFirst().status());
        }
    }

    @Test
    void simultaneousRequestsNeverMixTheirContextData() throws Exception {
        var bothStarted = new CountDownLatch(2);
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("shared-handler", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> {
                    bothStarted.countDown();
                    assertTrue(bothStarted.await(2, TimeUnit.SECONDS));
                    c.setAttribute("id", c.getInput());
                    c.setOutput("店铺-" + c.getInput());
                }));
        registry.freeze();
        try (var workers = Executors.newFixedThreadPool(2); var callers = Executors.newFixedThreadPool(2)) {
            var engine = new TaskChainEngine(registry, workers, workers, Duration.ofSeconds(3));
            var first = callers.submit(() -> engine.executeChain("shop", new TaskContext<Integer, String>(7)));
            var second = callers.submit(() -> engine.executeChain("shop", new TaskContext<Integer, String>(8)));
            var a = first.get(3, TimeUnit.SECONDS);
            var b = second.get(3, TimeUnit.SECONDS);
            assertTrue(a.isSuccess());
            assertTrue(b.isSuccess());
            assertEquals("店铺-7", a.getOutput());
            assertEquals(7, a.getAttribute("id"));
            assertEquals("店铺-8", b.getOutput());
            assertEquals(8, b.getAttribute("id"));
        }
    }

    @Test
    void callerInterruptionEndsTheStageAndPreservesInterruptStatus() throws Exception {
        var entered = new CountDownLatch(1);
        var release = new CountDownLatch(1);
        var returned = new CountDownLatch(1);
        var interrupted = new AtomicBoolean();
        var result = new AtomicReference<TaskContext<Integer, String>>();
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("blocked", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> { entered.countDown(); release.await(); c.setOutput("不应提交"); }));
        registry.freeze();
        try (var workers = Executors.newFixedThreadPool(2)) {
            var engine = new TaskChainEngine(registry, workers, workers, Duration.ofSeconds(5));
            var caller = new Thread(() -> {
                try {
                    result.set(engine.executeChain("shop", new TaskContext<Integer, String>(7)));
                    interrupted.set(Thread.currentThread().isInterrupted());
                } finally { returned.countDown(); }
            });
            try {
                caller.start();
                assertTrue(entered.await(2, TimeUnit.SECONDS));
                caller.interrupt();
                assertTrue(returned.await(2, TimeUnit.SECONDS));
                assertTrue(interrupted.get());
                assertFalse(result.get().isSuccess());
                assertInstanceOf(InterruptedException.class, result.get().getError());
                assertNull(result.get().getOutput());
            } finally { release.countDown(); caller.join(2000); }
        }
    }

    @Test
    void serialNodesShareOneBudgetInsteadOfReceivingFreshTimeouts() {
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("first", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> { Thread.sleep(450); c.setAttribute("draft", "阶段内结果"); }));
        registry.register(new TaskNodeHolder<Integer, String>("second", "shop", ProcessPhase.DATA_PROCESSING,
                1, TaskType.CPU_BOUND, true, c -> { Thread.sleep(450); c.setOutput("不应接受"); }));
        registry.freeze();
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofMillis(750))
                    .executeChain("shop", new TaskContext<Integer, String>(7));
            assertFalse(result.isSuccess());
            assertInstanceOf(TimeoutException.class, result.getError());
            assertEquals(NodeExecutionStatus.SUCCESS, result.getNodeResults().getFirst().status());
            assertEquals(NodeExecutionStatus.TIMED_OUT, result.getNodeResults().getLast().status());
            assertNull(result.getAttribute("draft"));
        }
    }

    @ParameterizedTest
    @CsvSource({"SERIAL,false", "SERIAL,true", "PARALLEL,false", "PARALLEL,true"})
    void rejectionIsDiagnosedAndRespectsNodeImportance(ExecutionMode mode, boolean required) {
        var rejected = new RejectedExecutionException("执行器已饱和");
        Executor io = command -> { throw rejected; };
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("rejected", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.IO_BOUND, required, c -> fail("被拒绝的节点不能运行")));
        registry.register(new TaskNodeHolder<Integer, String>("later", "shop", ProcessPhase.DATA_PROCESSING,
                1, TaskType.CPU_BOUND, true, c -> c.setOutput("仍可继续")));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(2))
                    .executePhaseChain("shop", new TaskContext<Integer, String>(7),
                            List.of(new PhaseConfig(ProcessPhase.DATA_PROCESSING, mode, Duration.ofSeconds(2))));
            assertEquals(!required, result.isSuccess());
            assertSame(rejected, result.getNodeResults().getFirst().cause());
            assertEquals(NodeExecutionStatus.FAILED, result.getNodeResults().getFirst().status());
            assertEquals(required ? null : "仍可继续", result.getOutput());
            if (required) assertSame(rejected, result.getError());
            else assertNull(result.getError());
        }
    }

    @Test
    void configuredPhaseOrderControlsExecutionAndSerialUpdatesCanReplaceResults() {
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("last-enum-first", "shop", ProcessPhase.POST_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> { c.setAttribute("value", "先"); c.setOutput("先"); }));
        registry.register(new TaskNodeHolder<Integer, String>("first-enum-last", "shop", ProcessPhase.PRE_VALIDATION,
                0, TaskType.CPU_BOUND, true, c -> { c.setAttribute("value", c.getAttribute("value") + "后"); c.setOutput(null); }));
        registry.register(new TaskNodeHolder<Integer, String>("unselected", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> fail("未选择的阶段不执行")));
        registry.freeze();
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(2))
                    .executePhaseChain("shop", new TaskContext<Integer, String>(7), List.of(
                            new PhaseConfig(ProcessPhase.POST_PROCESSING, ExecutionMode.SERIAL, Duration.ofSeconds(2)),
                            new PhaseConfig(ProcessPhase.PRE_PROCESSING, ExecutionMode.PARALLEL, Duration.ofSeconds(2)),
                            new PhaseConfig(ProcessPhase.PRE_VALIDATION, ExecutionMode.SERIAL, Duration.ofSeconds(2))));
            assertTrue(result.isSuccess());
            assertEquals("先后", result.getAttribute("value"));
            assertTrue(result.hasOutput());
            assertNull(result.getOutput());
            assertEquals(3, result.getPhaseResults().size());
            assertEquals(2, result.getNodeResults().size());
        }
    }

    @Test
    void requiredFailureReturnsBeforeBlockedPeerAndLateWritesCannotChangeResult() throws Exception {
        var registry = new TaskNodeRegistry();
        var blocked = new CountDownLatch(1);
        var release = new CountDownLatch(1);
        var lateFinished = new CountDownLatch(1);
        var fatal = new IllegalStateException("首先观察到的致命错误");
        registry.register(new TaskNodeHolder<Integer, String>("blocked", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.IO_BOUND, true, c -> {
                    blocked.countDown();
                    awaitIgnoringInterrupts(release);
                    c.setAttribute("late", "迟到数据");
                    c.setOutput("迟到响应");
                    lateFinished.countDown();
                }));
        registry.register(new TaskNodeHolder<Integer, String>("optional", "shop", ProcessPhase.DATA_PROCESSING,
                1, TaskType.CPU_BOUND, false, c -> { throw new IllegalStateException("可选错误"); }));
        registry.register(new TaskNodeHolder<Integer, String>("fatal", "shop", ProcessPhase.DATA_PROCESSING,
                2, TaskType.CPU_BOUND, true, c -> {
                    assertTrue(blocked.await(2, TimeUnit.SECONDS));
                    throw fatal;
                }));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(2); var io = Executors.newFixedThreadPool(2);
             var caller = Executors.newSingleThreadExecutor()) {
            try {
                var future = caller.submit(() -> new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(5))
                        .executePhaseChain("shop", new TaskContext<Integer, String>(7),
                                List.of(new PhaseConfig(ProcessPhase.DATA_PROCESSING, ExecutionMode.PARALLEL, Duration.ofSeconds(5)))));
                var result = future.get(2, TimeUnit.SECONDS);
                assertFalse(result.isSuccess());
                assertSame(fatal, result.getError());
                var reports = result.getNodeResults();
                assertEquals(NodeExecutionStatus.ABANDONED, reports.getFirst().status());
                assertEquals(1, release.getCount());
                release.countDown();
                assertTrue(lateFinished.await(2, TimeUnit.SECONDS));
                assertNull(result.getOutput());
                assertNull(result.getAttribute("late"));
                assertEquals(reports, result.getNodeResults());
                assertSame(fatal, result.getError());
            } finally { release.countDown(); }
        }
    }

    @ParameterizedTest
    @CsvSource({"SERIAL,false", "SERIAL,true", "PARALLEL,false", "PARALLEL,true"})
    void stageDeadlineDistinguishesOptionalAndRequiredUnfinishedNodes(ExecutionMode mode, boolean required) throws Exception {
        var registry = new TaskNodeRegistry();
        var release = new CountDownLatch(1);
        var lateFinished = new CountDownLatch(1);
        registry.register(new TaskNodeHolder<Integer, String>("ready", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> c.setAttribute("accepted", "成功数据")));
        registry.register(new TaskNodeHolder<Integer, String>("slow", "shop", ProcessPhase.DATA_PROCESSING,
                1, TaskType.IO_BOUND, required, c -> {
                    awaitIgnoringInterrupts(release);
                    c.setAttribute("late", "迟到数据");
                    lateFinished.countDown();
                }));
        registry.register(new TaskNodeHolder<Integer, String>("later", "shop", ProcessPhase.POST_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> c.setOutput((String) c.getAttribute("accepted"))));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(2); var io = Executors.newFixedThreadPool(2);
             var caller = Executors.newSingleThreadExecutor()) {
            try {
                var future = caller.submit(() -> new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(2))
                        .executePhaseChain("shop", new TaskContext<Integer, String>(7), List.of(
                                new PhaseConfig(ProcessPhase.DATA_PROCESSING, mode, Duration.ofMillis(150)),
                                new PhaseConfig(ProcessPhase.POST_PROCESSING, ExecutionMode.SERIAL, Duration.ofSeconds(2)))));
                var result = future.get(2, TimeUnit.SECONDS);
                assertEquals(!required, result.isSuccess());
                assertEquals(required ? null : "成功数据", result.getOutput());
                assertEquals(required ? null : "成功数据", result.getAttribute("accepted"));
                assertEquals(NodeExecutionStatus.TIMED_OUT, result.getNodeResults().get(1).status());
                if (required) assertInstanceOf(TimeoutException.class, result.getError());
                else assertNull(result.getError());
                var reports = result.getNodeResults();
                release.countDown();
                assertTrue(lateFinished.await(2, TimeUnit.SECONDS));
                assertNull(result.getAttribute("late"));
                assertEquals(reports, result.getNodeResults());
            } finally { release.countDown(); }
        }
    }

    private static void awaitIgnoringInterrupts(CountDownLatch latch) {
        boolean interrupted = false;
        for (;;) {
            try { latch.await(); break; }
            catch (InterruptedException ignored) { interrupted = true; }
        }
        if (interrupted) Thread.currentThread().interrupt();
    }

    @ParameterizedTest
    @ValueSource(strings = {"attribute", "remove", "output"})
    void parallelConflictsRejectTheWholePhaseEvenForOptionalNodes(String conflict) {
        var registry = new TaskNodeRegistry();
        for (int i = 0; i < 2; i++) {
            int index = i;
            registry.register(new TaskNodeHolder<Integer, String>("node-" + i, "shop", ProcessPhase.DATA_PROCESSING,
                    i, TaskType.CPU_BOUND, false, c -> {
                        c.setAttribute("unique-" + index, index);
                        switch (conflict) {
                            case "attribute" -> c.setAttribute("same", "同值也冲突");
                            case "remove" -> { if (index == 0) c.removeAttribute("same"); else c.setAttribute("same", "替换"); }
                            case "output" -> c.setOutput(null);
                            default -> throw new AssertionError(conflict);
                        }
                    }));
        }
        registry.freeze();
        var context = new TaskContext<Integer, String>(7);
        context.setAttribute("same", "原值");
        context.setOutput("原响应");
        try (var cpu = Executors.newFixedThreadPool(2); var io = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(2))
                    .executePhaseChain("shop", context,
                            List.of(new PhaseConfig(ProcessPhase.DATA_PROCESSING, ExecutionMode.PARALLEL, Duration.ofSeconds(2))));
            assertFalse(result.isSuccess());
            assertNotNull(result.getError());
            assertEquals("原值", result.getAttribute("same"));
            assertEquals("原响应", result.getOutput());
            assertFalse(result.getAttributes().containsKey("unique-0"));
            assertFalse(result.getAttributes().containsKey("unique-1"));
        }
    }

    @Test
    void parallelNodesReadTheSameSnapshotAndCommitOnlyTheirOwnWrites() {
        var registry = new TaskNodeRegistry();
        var firstWrote = new CountDownLatch(1);
        var secondRead = new CountDownLatch(1);
        registry.register(new TaskNodeHolder<Integer, String>("first", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.IO_BOUND, true, c -> {
                    c.setAttribute("first", "甲");
                    firstWrote.countDown();
                    assertTrue(secondRead.await(2, TimeUnit.SECONDS));
                }));
        registry.register(new TaskNodeHolder<Integer, String>("second", "shop", ProcessPhase.DATA_PROCESSING,
                1, TaskType.CPU_BOUND, true, c -> {
                    assertTrue(firstWrote.await(2, TimeUnit.SECONDS));
                    assertNull(c.getAttribute("first"));
                    c.setAttribute("second", "乙");
                    secondRead.countDown();
                }));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(2); var io = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(2))
                    .executePhaseChain("shop", new TaskContext<Integer, String>(7),
                            List.of(new PhaseConfig(ProcessPhase.DATA_PROCESSING, ExecutionMode.PARALLEL, Duration.ofSeconds(3))));
            assertTrue(result.isSuccess());
            assertEquals("甲", result.getAttribute("first"));
            assertEquals("乙", result.getAttribute("second"));
        }
    }

    @Test
    void requiredFailureRollsBackItsWholePhaseAndReportsUnexecutedNodes() {
        var registry = new TaskNodeRegistry();
        var fatal = new IllegalStateException("必需查询失败");
        registry.register(new TaskNodeHolder<Integer, String>("prior", "shop", ProcessPhase.PRE_VALIDATION,
                0, TaskType.CPU_BOUND, true, c -> c.setAttribute("prior", "已提交")));
        registry.register(new TaskNodeHolder<Integer, String>("first", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> c.setAttribute("draft", "阶段内结果")));
        registry.register(new TaskNodeHolder<Integer, String>("fatal", "shop", ProcessPhase.DATA_PROCESSING,
                1, TaskType.IO_BOUND, true, c -> { throw fatal; }));
        registry.register(new TaskNodeHolder<Integer, String>("skipped", "shop", ProcessPhase.DATA_PROCESSING,
                2, TaskType.CPU_BOUND, true, c -> fail("失败后不应继续节点")));
        registry.register(new TaskNodeHolder<Integer, String>("later", "shop", ProcessPhase.POST_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> fail("失败后不应进入后续阶段")));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(2); var io = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(2))
                    .executeChain("shop", new TaskContext<Integer, String>(7));
            assertFalse(result.isSuccess());
            assertSame(fatal, result.getError());
            assertEquals("已提交", result.getAttribute("prior"));
            assertNull(result.getAttribute("draft"));
            assertEquals(NodeExecutionStatus.NOT_EXECUTED, result.getNodeResults().stream()
                    .filter(r -> r.nodeId().equals("skipped")).findFirst().orElseThrow().status());
            assertEquals(NodeExecutionStatus.NOT_EXECUTED, result.getNodeResults().stream()
                    .filter(r -> r.nodeId().equals("later")).findFirst().orElseThrow().status());
        }
    }

    @Test
    void optionalFailureDiscardsItsWritesAndContinues() {
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>(
                "optional", "shop", ProcessPhase.DATA_PROCESSING, 0, TaskType.IO_BOUND, false,
                context -> {
                    context.setAttribute("leak", "错误结果");
                    context.setOutput("错误响应");
                    throw new IllegalStateException("辅助查询失败");
                }));
        registry.register(new TaskNodeHolder<Integer, String>(
                "required", "shop", ProcessPhase.DATA_PROCESSING, 1, TaskType.CPU_BOUND, true,
                context -> {
                    assertNull(context.getAttribute("leak"));
                    assertNull(context.getOutput());
                    context.setOutput("正常响应");
                }));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(2); var io = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(2))
                    .executeChain("shop", new TaskContext<Integer, String>(7));
            assertTrue(result.isSuccess());
            assertEquals("正常响应", result.getOutput());
            assertFalse(result.getAttributes().containsKey("leak"));
        }
    }

    @Test
    void serialNodesPassAcceptedDataToFollowingNodes() {
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>(
                "load", "shop", ProcessPhase.DATA_PROCESSING, 0, TaskType.IO_BOUND, true,
                context -> context.setAttribute("name", "店铺-" + context.getInput())));
        registry.register(new TaskNodeHolder<Integer, String>(
                "render", "shop", ProcessPhase.DATA_PROCESSING, 1, TaskType.CPU_BOUND, true,
                context -> context.setOutput((String) context.getAttribute("name"))));
        registry.freeze();
        try (var cpu = Executors.newFixedThreadPool(2); var io = Executors.newFixedThreadPool(2)) {
            var engine = new TaskChainEngine(registry, cpu, io, Duration.ofSeconds(2));
            TaskContext<Integer, String> result = engine.executeChain("shop", new TaskContext<>(7));
            assertTrue(result.isSuccess());
            assertEquals("店铺-7", result.getOutput());
        }
    }
}

package com.dianping.shared.taskchain;

import com.dianping.shared.taskchain.enums.ExecutionMode;
import com.dianping.shared.taskchain.enums.ProcessPhase;
import com.dianping.shared.taskchain.enums.TaskType;
import com.dianping.shared.taskchain.enums.NodeExecutionStatus;
import com.dianping.shared.taskchain.model.*;
import com.dianping.shared.taskchain.service.TaskChainEngine;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import java.time.Duration;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.jupiter.api.Assertions.*;

/** 业务子类必须在真实引擎执行中保留类型，并沿用局部写入及阶段提交语义。 */
class TaskContextInheritanceTest {
    @Test
    void serialNodesReceiveBusinessSubtypeAndPassBusinessPropertiesToTheRoot() {
        var first = new AtomicReference<BusinessContext>();
        var registry = new TaskNodeRegistry();
        registry.register(node("load", 0, true, context -> {
            var business = assertInstanceOf(BusinessContext.class, context);
            first.set(business);
            assertEquals(7L, business.getShopId());
            business.setName("店铺-7");
        }));
        registry.register(node("assemble", 1, true, context -> {
            var business = assertInstanceOf(BusinessContext.class, context);
            assertNotSame(first.get(), business);
            business.setOutput(business.getName() + "-详情");
        }));
        registry.freeze();
        var root = new BusinessContext(7L);
        try (var pool = Executors.newFixedThreadPool(2)) {
            BusinessContext result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(3))
                    .executeChain("shop", root);
            assertSame(root, result);
            assertTrue(result.isSuccess(), () -> String.valueOf(result.getError()));
            assertEquals("店铺-7", result.getName());
            assertEquals("店铺-7-详情", result.getOutput());
            assertThrows(IllegalStateException.class, () -> first.get().setName("迟到结果"));
            assertThrows(IllegalStateException.class, () -> root.setName("修改已返回结果"));
            assertThrows(IllegalStateException.class, () -> first.get().beginExecution());
        }
    }

    @Test
    void parallelBusinessContextsReadTheSameSnapshotAndMergeDistinctProperties() {
        var written = new CountDownLatch(1);
        var observed = new CountDownLatch(1);
        var registry = new TaskNodeRegistry();
        registry.register(node("name", 0, true, context -> {
            var business = (BusinessContext) context;
            business.setName("新名称");
            written.countDown();
            assertTrue(observed.await(2, TimeUnit.SECONDS));
        }));
        registry.register(node("count", 1, true, context -> {
            assertTrue(written.await(2, TimeUnit.SECONDS));
            var business = (BusinessContext) context;
            try {
                assertEquals("初始名称", business.getName());
                business.setCount(3);
            } finally { observed.countDown(); }
        }));
        registry.freeze();
        var root = new BusinessContext(7L);
        root.setName("初始名称");
        try (var pool = Executors.newFixedThreadPool(2)) {
            BusinessContext result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(3))
                    .executePhaseChain("shop", root, parallel());
            assertTrue(result.isSuccess(), () -> String.valueOf(result.getError()));
            assertEquals("新名称", result.getName());
            assertEquals(3, result.getCount());
        }
    }

    @Test
    void parallelBusinessPropertyConflictRejectsTheWholeStage() {
        var registry = new TaskNodeRegistry();
        registry.register(node("first", 0, true, c -> ((BusinessContext) c).setName("甲")));
        registry.register(node("second", 1, true, c -> ((BusinessContext) c).setName("乙")));
        registry.freeze();
        var root = new BusinessContext(7L);
        root.setName("原始名称");
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(3))
                    .executePhaseChain("shop", root, parallel());
            assertFalse(result.isSuccess());
            assertInstanceOf(IllegalStateException.class, result.getError());
            assertEquals("原始名称", result.getName());
        }
    }

    @Test
    void failedBusinessNodeCannotLeakItsPropertiesIntoTheNextNode() {
        var registry = new TaskNodeRegistry();
        registry.register(node("optional", 0, false, c -> {
            ((BusinessContext) c).setName("无效名称");
            c.fail(new IllegalStateException("可选节点失败"));
        }));
        registry.register(node("assemble", 1, true, c -> c.setOutput(((BusinessContext) c).getName())));
        registry.freeze();
        var root = new BusinessContext(7L);
        root.setName("原始名称");
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(3)).executeChain("shop", root);
            assertTrue(result.isSuccess());
            assertEquals("原始名称", result.getOutput());
            assertEquals(NodeExecutionStatus.FAILED, result.getNodeResults().getFirst().status());
        }
    }

    @ParameterizedTest
    @ValueSource(booleans = {false, true})
    void invalidSubtypeFactoryIsReportedAsNodeFailure(boolean required) {
        // 未覆盖工厂时不能悄悄给业务节点一个基类上下文。
        var root = new TaskContext<Long, String>(7L) { };
        var registry = new TaskNodeRegistry();
        registry.register(node("invalid", 0, required, c -> fail("非法上下文不应交给业务节点")));
        registry.freeze();
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(3)).executeChain("shop", root);
            assertEquals(!required, result.isSuccess());
            assertEquals(NodeExecutionStatus.FAILED, result.getNodeResults().getFirst().status());
            assertInstanceOf(IllegalStateException.class, result.getNodeResults().getFirst().cause());
            assertThrows(IllegalStateException.class, () -> root.setOutput("执行已结束"));
        }
    }

    @Test
    void nodeFactoryCannotReturnAnotherExecutionOrReuseANode() {
        class InvalidContext extends TaskContext<Long, String> {
            private TaskContext<Long, String> next;
            InvalidContext() { super(7L); }
            InvalidContext(InvalidContext parent, Snapshot<String> snapshot) { super(parent, snapshot); }
            @Override protected TaskContext<Long, String> createNodeContext(Snapshot<String> snapshot) { return next; }
        }
        var root = new InvalidContext();
        var execution = root.beginExecution();
        var snapshot = execution.snapshot();
        root.next = root;
        assertThrows(IllegalStateException.class, () -> execution.nodeContext(snapshot));
        root.next = new InvalidContext(new InvalidContext(), snapshot);
        assertThrows(IllegalStateException.class, () -> execution.nodeContext(snapshot));
        root.next = new InvalidContext(root, snapshot);
        var node = execution.nodeContext(snapshot);
        assertThrows(IllegalStateException.class, () -> execution.nodeContext(snapshot));
        execution.finishNode(node);
        assertThrows(IllegalStateException.class, () -> execution.nodeContext(snapshot));
    }

    private static TaskNodeHolder<Long, String> node(String id, int order, boolean required, TaskNodeHandler<Long, String> handler) {
        return new TaskNodeHolder<>(id, "shop", ProcessPhase.DATA_PROCESSING, order, TaskType.CPU_BOUND, required, handler);
    }

    private static List<PhaseConfig> parallel() {
        return List.of(new PhaseConfig(ProcessPhase.DATA_PROCESSING, ExecutionMode.PARALLEL, Duration.ofSeconds(3)));
    }

    private static final class BusinessContext extends TaskContext<Long, String> {
        BusinessContext(Long shopId) { super(shopId); }
        private BusinessContext(BusinessContext parent, Snapshot<String> snapshot) { super(parent, snapshot); }
        @Override protected BusinessContext createNodeContext(Snapshot<String> snapshot) { return new BusinessContext(this, snapshot); }
        Long getShopId() { return getInput(); }
        String getName() { return (String) getAttribute("name"); }
        void setName(String name) { setAttribute("name", name); }
        Integer getCount() { return (Integer) getAttribute("count"); }
        void setCount(Integer count) { setAttribute("count", count); }
    }
}

package com.dianping.shared.taskchain;

import com.dianping.shared.taskchain.enums.ProcessPhase;
import com.dianping.shared.taskchain.enums.TaskType;
import com.dianping.shared.taskchain.model.*;
import com.dianping.shared.taskchain.service.TaskChainEngine;
import org.junit.jupiter.api.Test;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class TaskContextTest {
    @Test
    void visibleAttributesAndReportsAreReadOnlyContainerSnapshots() {
        var input = new HashMap<String, String>();
        input.put("shop", "店铺-7");
        var context = new TaskContext<Map<String, String>, String>(input);
        context.setAttribute("seed", "初始属性");
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Map<String, String>, String>("read", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> {
                    assertThrows(UnsupportedOperationException.class, () -> c.getAttributes().clear());
                    assertThrows(IllegalStateException.class, c::beginExecution);
                    c.setOutput(c.getInput().get("shop"));
                }));
        registry.freeze();
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(2)).executeChain("shop", context);
            assertTrue(result.isSuccess(), () -> String.valueOf(result.getError()));
            assertEquals("店铺-7", result.getOutput());
            assertEquals("初始属性", result.getAttribute("seed"));
            assertThrows(UnsupportedOperationException.class, () -> result.getAttributes().clear());
            assertThrows(UnsupportedOperationException.class, () -> result.getNodeResults().clear());
            assertThrows(IllegalStateException.class, () -> result.setOutput("覆盖已返回响应"));
        }
    }

    @Test
    void concreteCollectionInputsOutputsAndAttributeValuesKeepTheirDeclaredTypes() {
        var input = new HashMap<String, String>();
        input.put("shop", "店铺-7");
        var output = new ArrayList<String>();
        output.add("店铺-7");
        var value = new TreeMap<String, String>();
        value.put("name", "店铺-7");
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<HashMap<String, String>, ArrayList<String>>("node", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> {
                    assertEquals("店铺-7", c.getInput().get("shop"));
                    c.setAttribute("value", value);
                    c.setOutput(output);
                }));
        registry.freeze();
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(2))
                    .executeChain("shop", new TaskContext<HashMap<String, String>, ArrayList<String>>(input));
            assertTrue(result.isSuccess(), () -> String.valueOf(result.getError()));
            assertSame(input, result.getInput());
            assertSame(output, result.getOutput());
            assertSame(value, result.getAttribute("value"));
        }
    }

    @Test
    void oneContextCannotRunConcurrentlyOrBeExecutedAgain() throws Exception {
        var started = new CountDownLatch(1);
        var release = new CountDownLatch(1);
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("node", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, true, c -> { started.countDown(); release.await(); c.setOutput("完成"); }));
        registry.freeze();
        try (var workers = Executors.newFixedThreadPool(2); var caller = Executors.newSingleThreadExecutor()) {
            var engine = new TaskChainEngine(registry, workers, workers, Duration.ofSeconds(3));
            var context = new TaskContext<Integer, String>(7);
            try {
                var first = caller.submit(() -> engine.executeChain("shop", context));
                assertTrue(started.await(2, TimeUnit.SECONDS));
                assertThrows(IllegalStateException.class, () -> engine.executeChain("shop", context));
                release.countDown();
                assertTrue(first.get(2, TimeUnit.SECONDS).isSuccess());
                assertThrows(IllegalStateException.class, () -> engine.executeChain("shop", context));
            } finally { release.countDown(); }
        }
    }

    @Test
    void explicitNodeFailureDiscardsLocalWritesWithoutPoisoningOptionalChain() {
        var cause = new IllegalArgumentException("主动标记失败");
        var registry = new TaskNodeRegistry();
        registry.register(new TaskNodeHolder<Integer, String>("optional", "shop", ProcessPhase.DATA_PROCESSING,
                0, TaskType.CPU_BOUND, false, c -> { c.setOutput("无效"); c.fail(cause); }));
        registry.freeze();
        try (var pool = Executors.newFixedThreadPool(2)) {
            var result = new TaskChainEngine(registry, pool, pool, Duration.ofSeconds(2))
                    .executeChain("shop", new TaskContext<Integer, String>(7));
            assertTrue(result.isSuccess());
            assertNull(result.getError());
            assertNull(result.getOutput());
            assertSame(cause, result.getNodeResults().getFirst().cause());
        }
    }
}

