package com.dianping.shared.taskchain.config;

import com.dianping.shared.taskchain.annotation.TaskNode;
import com.dianping.shared.taskchain.model.TaskNodeHandler;
import com.dianping.shared.taskchain.model.TaskNodeHolder;
import com.dianping.shared.taskchain.model.TaskNodeRegistry;
import com.dianping.shared.taskchain.service.TaskChainEngine;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.aop.support.AopUtils;
import org.springframework.core.annotation.AnnotatedElementUtils;
import java.util.List;

@Configuration(proxyBeanMethods = false)
@EnableConfigurationProperties(TaskChainProperties.class)
public class TaskChainConfiguration {

    //创建线程池管理对象
    //复习一下，注册为bean就是把这个方法返回的对象交给Spring管理
    @Bean(destroyMethod = "close")//规定销毁bean时调用它自己定义的close方法
    public TaskChainExecutors taskChainExecutors(TaskChainProperties properties) {
        return new TaskChainExecutors(properties);
    }

    @Bean//创建注册表                //这里生命的是一个集合，因此Spring会收集容器中匹配TaskNodeHandler类型的bean
    public TaskNodeRegistry taskNodeRegistry(List<TaskNodeHandler<?, ?>> handlers) {
        var registry = new TaskNodeRegistry();
        for (var handler : handlers) {
            //从每个节点上读取元数据
            var metadata = AnnotatedElementUtils.findMergedAnnotation(AopUtils.getTargetClass(handler), TaskNode.class);
            if (metadata == null) throw new IllegalArgumentException("任务处理器缺少 @TaskNode：" + handler.getClass().getName());
            register(registry, handler, metadata);
        }
        registry.freeze();
        return registry;
    }

    private static <I, O> void register(TaskNodeRegistry registry, TaskNodeHandler<I, O> handler, TaskNode metadata) {
        registry.register(new TaskNodeHolder<>(metadata.nodeId(), metadata.nodeName(), metadata.description(),
                metadata.group(), metadata.phase(), metadata.order(),
                metadata.taskType(), metadata.required(), handler));
    }

    @Bean
    public TaskChainEngine taskChainEngine(TaskNodeRegistry registry, TaskChainExecutors executors,
                                           TaskChainProperties properties) {
        return new TaskChainEngine(registry, executors.cpuExecutor(), executors.ioExecutor(), properties.getDefaultPhaseTimeout());
    }
}

package com.dianping.shared.taskchain.config;

import java.time.Duration;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/** 两个有界池共享一次关闭预算，拒绝时绝不在协调线程运行节点。 */
public final class TaskChainExecutors implements AutoCloseable {

    private final ThreadPoolExecutor cpuExecutor;
    private final ThreadPoolExecutor ioExecutor;
    //应用关闭时，等待线程池中已有任务完成的最长等待时间，超时后对线程池调用shutDownNow尝试中断
    private final Duration shutdownTimeout;
    private final AtomicBoolean closed = new AtomicBoolean();

    public TaskChainExecutors(TaskChainProperties properties) {
        properties.validate();
        shutdownTimeout = properties.getShutdownTimeout();
        cpuExecutor = create(properties.getCpuThreads(), properties.getQueueCapacity(), "taskchain-cpu-");
        ioExecutor = create(properties.getIoThreads(), properties.getQueueCapacity(), "taskchain-io-");
    }

    public ThreadPoolExecutor cpuExecutor() { return cpuExecutor; }
    public ThreadPoolExecutor ioExecutor() { return ioExecutor; }


    private static ThreadPoolExecutor create(int threads, int capacity, String prefix) {
        //配置工作线程的参数
        ThreadFactory factory = Thread.ofPlatform()
                .name(prefix, 1)
                .inheritInheritableThreadLocals(false)
                .daemon(false)
                .factory();
        return new ThreadPoolExecutor(
                threads, //核心线程数
                threads, //最大线程数
                0,//空闲存活时间
                TimeUnit.MILLISECONDS,
                new ArrayBlockingQueue<>(capacity),//有界等待队列，限制挤压量，防止任务无限增长
                factory,
                new ThreadPoolExecutor.AbortPolicy()//拒绝策略，在线程池无法接收业务时直接抛出异常
        );
    }

    @Override
    public void close() {
        //防止重复修改
        if (!closed.compareAndSet(false, true)) return;
        long start = System.nanoTime();
        long budget = shutdownTimeout.toNanos();
        cpuExecutor.shutdown();
        ioExecutor.shutdown();
        boolean interrupted = false;
        try {
            await(cpuExecutor, budget - (System.nanoTime() - start));
            await(ioExecutor, budget - (System.nanoTime() - start));
        } catch (InterruptedException error) {
            interrupted = true;
        } finally {
            //两个池共享等待时间
            if (!cpuExecutor.isTerminated()) cpuExecutor.shutdownNow();
            if (!ioExecutor.isTerminated()) ioExecutor.shutdownNow();
            if (interrupted) Thread.currentThread().interrupt();
        }
    }

    private static void await(ThreadPoolExecutor executor, long remaining) throws InterruptedException {
        if (remaining > 0) executor.awaitTermination(remaining, TimeUnit.NANOSECONDS);
    }
}

package com.dianping.shared.taskchain.config;

import lombok.Getter;
import lombok.Setter;
import org.springframework.boot.context.properties.ConfigurationProperties;
import java.time.Duration;

@Setter
@Getter
@ConfigurationProperties(prefix = "taskchain")
public class TaskChainProperties {
    //线程数
    private int cpuThreads = Math.max(1, Runtime.getRuntime().availableProcessors());
    private int ioThreads = Math.max(4, 2 * Runtime.getRuntime().availableProcessors());
    //队列数量
    private int queueCapacity = 128;
    private Duration defaultPhaseTimeout = Duration.ofMillis(3000);
    //阶段执行的超时时间
    private Duration shutdownTimeout = Duration.ofSeconds(5);

    //参数校验
    public void validate() {
        if (cpuThreads <= 0 || ioThreads <= 0 || queueCapacity <= 0) {
            throw new IllegalArgumentException("任务链线程数与队列容量必须为正数");
        }
        validateDuration(defaultPhaseTimeout, "默认阶段预算");
        validateDuration(shutdownTimeout, "关闭等待预算");
    }

    private static void validateDuration(Duration duration, String name) {
        if (duration == null || duration.isZero() || duration.isNegative()) {
            throw new IllegalArgumentException(name + "必须为正数");
        }
        try { duration.toNanos(); }
        catch (ArithmeticException error) { throw new IllegalArgumentException(name + "超出纳秒计时范围", error); }
    }
}

